def maximumEnergy(energy: list[int], k: int) -> int:
    n = len(energy)
    dp = energy[:]  # dp[i] stores best energy sum starting at i
    # Process backwards, so dp[i+k] is already set
    for i in range(n - 1 - k, -1, -1):
        dp[i] += dp[i + k]
    return max(dp)
